#include <string>

struct TrieNode {
    TrieNode* children[26] = {};
    bool isEnd = false;
    TrieNode() = default;
    TrieNode(const TrieNode&) = delete;
    TrieNode& operator=(const TrieNode&) = delete;
    ~TrieNode() {
        for (TrieNode* child : children) {
            delete child;
        }
    }
};

void insert(TrieNode& root, const std::string& word) {
    TrieNode* node = &root;
    for (char c : word) {
        int i = c - 'a';
        if (node->children[i] == nullptr) {
            node->children[i] = new TrieNode();
        }
        node = node->children[i];
    }
    node->isEnd = true;
}

int countMatches(const TrieNode* node, const std::string& pattern, std::size_t i) {
    if (node == nullptr) {
        return 0;
    }
    if (i == pattern.size()) {
        return node->isEnd ? 1 : 0;
    }
    if (pattern[i] == '.') {
        int total = 0;
        for (const TrieNode* child : node->children) {
            total += countMatches(child, pattern, i + 1);
        }
        return total;
    }
    return countMatches(node->children[pattern[i] - 'a'], pattern, i + 1);
}

